('av_CGUuaAEyTN5FKdo_4bmj5aHKQLRlNXzFVB2gPgAngTdi4X3yE6PUHIiUJ2JkkffCn5V7trPLctzuER0','盗墓笔记之怒海潜沙 秦岭神树',2019,'series','中国大陆','国语','["国产剧","剧情","冒险","国产","电视剧"]','["成毅","侯明昊","李曼","张博宇","刘学义","任嘉伦","姚橹","姚奕辰"]','["李昂","刘国辉","周煜壹"]','https://gimg0.baidu.com/gimg/app=2001&n=0&g=0n&fmt=webp&src=img.baipiaozhe.com/assets/images/a8/a807fbf0f42f450ae3cf1e7459abf6b84fa19a790857c997efb0c2b2e0b90b83.webp',NULL,'主人公吴邪(侯明昊 饰)身为老九门吴家后人,从机关重重的战国墓“七星鲁王宫”九死一生逃出生天后,回到家中发现三叔吴三省(姚橹 饰)失踪,还牵扯出十几年前的一桩考古队谜案。吴邪接到神秘的阿宁来信,为找到三叔,他前去西沙明代沉船葬海底墓寻找线索,遇到自七星鲁王宫分别的王胖子(张博宇 饰),还发现神秘古物蛇眉铜鱼,以及失忆的张起灵(成毅 饰),而小哥来到西沙海底墓似乎还另有原因。在潜入神秘的明代船墓过程,遭遇海猴子、禁婆等怪物的攻击,最终突破奇门遁甲的层层机关返回陆地。然而蛇眉铜鱼、六角铜铃的线索又将他们指引到秦岭,去探寻巨大青铜树的秘密。','全40集',40,40,101.37,'2026-10-15T19:22:15.681Z'),
('av_CGwt13guWbKVN34L1QIEaFX3ehMhtwb8RpYTm-eXlb798Xd5rrlSWdG5YLeO_O-KyqvYZ6nIqHTUDfY','双骄',2024,'short_drama','中国大陆','国语','["短剧","反转爽剧","现代都市","脑洞悬疑"]','[]','[]','https://gimg0.baidu.com/gimg/app=2001&n=0&g=0n&fmt=webp&src=img.baipiaozhe.com/assets/images/91/918d0b9d722ed1f6b3252102d8d2de1b27704ec7a22c736c7bad50add144522d.webp',NULL,'','全66集',66,66,50.87,'2026-11-13T08:57:12.570Z'),
('av_CI8_z5xLM0UPAYGQqBqCD83ziY0uNx1VsUPQ1ACZ4PIS_kspoQfpukVt7o7nfdrLu9lQBMX7ACWjdAE','飞到我心上',2026,'series','中国大陆','国语','["国产剧","国产","连续剧","剧情","爱情","连续","电视剧"]','["刘些宁","魏哲鸣","马梦唯","马渝捷","季美含","费启鸣","金泽灏","徐梵溪","赵晴","赵煊","冯雷","傅淼"]','["郑世龙"]','https://gimg0.baidu.com/gimg/app=2001&n=0&g=0n&fmt=webp&src=img.baipiaozhe.com/assets/images/f8/f8e63c7387f838d43dfd5e32532aa841c8d0573bc4ce559fce034b0de12ddd55.webp','https://gimg0.baidu.com/gimg/app=2001&n=0&g=0n&fmt=webp&src=img.baipiaozhe.com/assets/images/3f/3f5a26410ef363d84256dfe36e383511f3ef3ce961a3d03a7e85e4e438ab23e9.webp','根据翘摇小说《降落我心上》改编。阮思娴本是一名怀揣着飞行员梦想的空乘,却因恒世航空取消飞行员培训计划而受挫,更因与世航副总裁傅明予的误会毅然辞职,转去学飞。三年后,阮思娴以第一名成绩从飞行学院毕业,成为众大航司争夺的对象。在追求机长梦想的路上,阮思娴遭遇了各种考验,在公司改革中,傅明予也面临多重阻碍。两人在梦想与现实时碰撞中,情感逐渐升温,却又因各种误会与挑战而渐行渐远。最终,两人在相互支持与理解中,终于降落在彼比的心上。','全24集',33,24,123.91,'2026-11-08T22:23:02.815Z'),
('av_CJ9JVDSRqQ-DWc4AdDnQ6jT2j9jTMh5CXWQ1E9c7dK6vEjdDNMwVaii_y5dEqhBJTBTWyhqPzVq3mVQ','性爱自修室 第1季',2019,'series','英国','国语','["欧美剧","剧情","喜剧","欧美","Netflix自制剧","美国"]','["阿萨·巴特菲尔德","艾玛·麦基","吉莲·安德森","舒提·盖特瓦","艾米·卢·伍德","凯达·威廉姆斯特灵","康纳·斯温德尔","米米·基恩","萨曼莎·斯毕洛","吉姆·霍威克","拉卡·塔克雷尔","埃利斯戴尔·皮特里"]','["本·泰勒","鲁尼亚罗·马普福莫","索菲·古德哈特","凯特·赫伦","艾丽斯·西布赖特","艾丽莎·麦克克莱兰","多米尼克·勒克莱尔","米歇尔·萨维尔"]','https://gimg0.baidu.com/gimg/app=2001&n=0&g=0n&fmt=webp&src=img.baipiaozhe.com/assets/images/c4/c4cde709247cde3ef22cd8f148eb65a0f13a1e3d9e89d203275780a9db39a3cb.webp','https://gimg0.baidu.com/gimg/app=2001&n=0&g=0n&fmt=webp&src=img.baipiaozhe.com/assets/images/ed/ed223e136f4ea9fe870af0f7187fce7e6b780275dd5edf97e1909f11816ea043.webp','随着莫戴尔中学的关闭,奥蒂斯和埃里克现在面临着新的挑战 — 迎接他们在卡文迪什第六学院的第一天。奥蒂斯担心能否成功建立新诊所,而埃里克则祈祷他们不会再次成为失败者。但对所有莫戴尔中学的学生来说,卡文迪什都是一种文化冲击 — 他们自认为进步开明,但这所新学院达到了另一个层面。这里的社区花园有每日瑜伽,有强烈的可持续发展氛围,还有一群因为...善良而受欢迎的孩子!小薇完全被这个学校以学生为主导的非竞争教学方式所折服,而杰克逊仍在努力忘记卡尔。艾梅选择了 Art A Level 课程,想要尝试一些新的东西,而亚当则在纠结主流教育是否适合他。美国这边,梅芙在著名的华莱士大学实现着她的梦想,师从异教作家托马斯·莫洛伊。奥蒂斯非常想念她,同时适应着自己不再是家中独子,也不再是校园里唯一的治疗师······','全8集',8,8,81.94,'2026-11-13T12:18:38.935Z'),
('av_CJBfQbXDK3MYy9SAQzfz5UM7ipu0CAeLB5cgo0hsy3-HyPnwcJtuB8xH6LXeTlebEskaW8QrBrvq9hk','爱情公寓 第4季',2014,'series','中国大陆','国语','["国产剧","喜剧","爱情","剧情","内地","国产"]','["娄艺潇","陈赫","孙艺洲","李佳航","王传君","赵文琪","邓家佳","榕榕","李金铭","金世佳","刘萌萌","赵霁"]','["韦正","未录入"]','https://gimg0.baidu.com/gimg/app=2001&n=0&g=0n&fmt=webp&src=img.baipiaozhe.com/assets/images/a0/a0babcdf9d598327f5740cd553b2651e48a5ebd7d12827a7889284432f4fd2c9.webp','https://gimg0.baidu.com/gimg/app=2001&n=0&g=0n&fmt=webp&src=img.baipiaozhe.com/assets/images/51/51e8a1d04e15087bc88c8f8777a1fa6958e31be3051c81a4125d1e68c43625af.webp',NULL,'全24集',NULL,NULL,187.35,'2026-11-09T15:24:18.460Z');
